m.ends_on" type="date" class="form-control" required></label><label><span>ملاحظات</span><input v-model="editForm.notes" class="form-control"></label><button class="btn btn-primary"><i class="bi bi-check2"></i> حفظ</button><button type="button" class="btn btn-light" @click="editingId=null">إلغاء</button></form></article><div v-if="!years.data.length" class="empty"><i class="bi bi-calendar2-x"></i><strong>لا توجد سنة مالية</strong><span>أنشئ الأولى مع خيار إنشاء الشهور تلقائياً.</span></div><Pagination :links="years.links"/></main></div></template>
